#!/usr/bin/env node
// tokens/tokens.json -> the per-platform token files in generated/.
//
//   node tools/tokens.mjs           write generated/*
//   node tools/tokens.mjs --check   exit 1 if any generated file differs from what it would write
//
// `render(tokens)` is the one function every platform file comes from; the
// check in tools/check.mjs calls it too, so "stale" means exactly "not what
// this function makes from tokens.json today".
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../', import.meta.url));
const HEADER = 'Generated by tools/tokens.mjs from tokens/tokens.json. Do not edit: change tokens.json and run `npm run tokens`.';
export const GENERATED = ['generated/tokens.css', 'generated/tokens.js', 'generated/Tokens.swift', 'generated/tokens.rs'];
const NAME = /^[a-z][A-Za-z0-9]*$/;

// Groups of plain numbers, as [path in tokens.json, CSS unit].
const NUMBER_GROUPS = [
  [['space'], 'px'], [['radius'], 'px'], [['stroke'], 'px'], [['opacity'], ''], [['size'], 'px'],
  [['type', 'size'], 'px'], [['type', 'weight'], ''], [['type', 'lineHeight'], ''], [['type', 'tracking'], 'em'],
  [['motion', 'duration'], 'ms'], [['motion', 'rate'], ''],
];

const kebab = (name) => name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const screaming = (name) => name.replace(/[A-Z]/g, (c) => `_${c}`).toUpperCase();
const pascal = (name) => name[0].toUpperCase() + name.slice(1);
const rgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
const hex2 = (n) => `0x${n.toString(16).toUpperCase().padStart(2, '0')}`;
const at = (tokens, path) => path.reduce((node, key) => node[key], tokens);
const f64 = (n) => (Number.isInteger(n) ? `${n}.0` : String(n));

/** Problems the JSON Schema cannot express: names usable as identifiers everywhere, ramps whose themes have the same length. */
export function problems(tokens) {
  const out = [];
  const names = (group, where) => { for (const key of Object.keys(group)) if (!NAME.test(key)) out.push(`${where}.${key}: token names are lowerCamelCase letters and digits`); };
  names(tokens.color, 'color');
  names(tokens.ramp, 'ramp');
  for (const [path] of NUMBER_GROUPS) names(at(tokens, path), path.join('.'));
  names(tokens.type.family, 'type.family');
  names(tokens.motion.easing, 'motion.easing');
  for (const [name, ramp] of Object.entries(tokens.ramp)) {
    if (ramp.light.length !== ramp.dark.length) out.push(`ramp.${name}: light has ${ramp.light.length} stops, dark ${ramp.dark.length}; they must match`);
  }
  return out;
}

function css(t) {
  const lines = [`/* ${HEADER} */`, '/* Lengths are points: 1 pt = 1 CSS px. */', ':root, :root[data-theme="light"] {'];
  const themed = (theme) => {
    const out = [];
    for (const [name, c] of Object.entries(t.color)) out.push(`  --zc-color-${kebab(name)}: ${c[theme]};`);
    for (const [name, r] of Object.entries(t.ramp)) r[theme].forEach((c, i) => out.push(`  --zc-ramp-${kebab(name)}-${i}: ${c};`));
    for (const name of Object.keys(t.ramp)) out.push(`  --zc-ramp-${kebab(name)}: linear-gradient(to right, ${t.ramp[name][theme].join(', ')});`);
    return out;
  };
  lines.push(...themed('light'));
  for (const [path, unit] of NUMBER_GROUPS) {
    for (const [name, { value }] of Object.entries(at(t, path))) lines.push(`  --zc-${path.map(kebab).join('-')}-${kebab(name)}: ${value}${unit};`);
  }
  for (const [name, { value }] of Object.entries(t.type.family)) lines.push(`  --zc-type-family-${kebab(name)}: ${!value.includes(',') && value.includes(' ') ? `"${value}"` : value};`);
  for (const [name, { value }] of Object.entries(t.motion.easing)) lines.push(`  --zc-motion-easing-${kebab(name)}: cubic-bezier(${value.join(', ')});`);
  lines.push('}', '@media (prefers-color-scheme: dark) {', '  :root:not([data-theme="light"]) {');
  lines.push(...themed('dark').map((line) => `  ${line}`));
  lines.push('  }', '}', ':root[data-theme="dark"] {', ...themed('dark'), '}', '');
  return lines.join('\n');
}

function js(t) {
  const strip = (group) => Object.fromEntries(Object.entries(group).map(([k, v]) => [k, v.value]));
  const color = { light: {}, dark: {} };
  for (const [name, c] of Object.entries(t.color)) { color.light[name] = c.light; color.dark[name] = c.dark; }
  const ramp = Object.fromEntries(Object.entries(t.ramp).map(([k, r]) => [k, { light: r.light, dark: r.dark }]));
  const typography = { family: strip(t.type.family), size: strip(t.type.size), weight: strip(t.type.weight), lineHeight: strip(t.type.lineHeight), tracking: strip(t.type.tracking) };
  const motion = { duration: strip(t.motion.duration), easing: strip(t.motion.easing), rate: strip(t.motion.rate) };
  const freeze = (name, value) => `export const ${name} = deepFreeze(${JSON.stringify(value, null, 2)});`;
  return [
    `// ${HEADER}`,
    '// Lengths are points (1 pt = 1 CSS px). WebGL paint takes these values directly; CSS reads generated/tokens.css.',
    'const deepFreeze = (value) => { for (const v of Object.values(value)) if (v && typeof v === \'object\') deepFreeze(v); return Object.freeze(value); };',
    freeze('color', color), freeze('ramp', ramp), freeze('space', strip(t.space)), freeze('radius', strip(t.radius)),
    freeze('stroke', strip(t.stroke)), freeze('opacity', strip(t.opacity)), freeze('size', strip(t.size)),
    freeze('typography', typography), freeze('motion', motion), '',
  ].join('\n');
}

function swift(t) {
  const doc = (text, indent) => `${indent}/// ${text.replace(/\n/g, ' ')}`;
  const c = (hex) => { const [r, g, b] = rgb(hex); return `ZCRGB(r: ${hex2(r)}, g: ${hex2(g)}, b: ${hex2(b)})`; };
  const numbers = (group, type = 'Double') => Object.entries(group).flatMap(([name, { value, description }]) => [doc(description, '        '), `        public static let ${name}: ${type} = ${value}`]);
  const lines = [
    `// ${HEADER}`,
    '// Lengths are points; durations milliseconds.',
    '',
    'public struct ZCRGB: Equatable, Hashable, Sendable {',
    '    public let r: UInt8',
    '    public let g: UInt8',
    '    public let b: UInt8',
    '}',
    '',
    'public struct ZCThemed<Value: Sendable>: Sendable {',
    '    public let light: Value',
    '    public let dark: Value',
    '    public func value(dark isDark: Bool) -> Value { isDark ? dark : light }',
    '}',
    '',
    'public enum ZCTokens {',
    '    public enum Color {',
    ...Object.entries(t.color).flatMap(([name, v]) => [doc(v.description, '        '), `        public static let ${name} = ZCThemed(light: ${c(v.light)}, dark: ${c(v.dark)})`]),
    '    }',
    '    public enum Ramp {',
    ...Object.entries(t.ramp).flatMap(([name, v]) => [doc(v.description, '        '), `        public static let ${name} = ZCThemed(light: [${v.light.map(c).join(', ')}], dark: [${v.dark.map(c).join(', ')}])`]),
    '    }',
  ];
  for (const [path] of NUMBER_GROUPS) {
    const [head, tail] = path;
    if (head === 'type' || head === 'motion') continue;
    lines.push(`    public enum ${pascal(head)} {`, ...numbers(at(t, path)), '    }');
  }
  lines.push('    public enum Typography {');
  lines.push('        public enum Family {', ...Object.entries(t.type.family).flatMap(([name, { value, description }]) => [doc(description, '            '), `            public static let ${name} = ${JSON.stringify(value)}`]), '        }');
  for (const key of ['size', 'weight', 'lineHeight', 'tracking']) lines.push(`        public enum ${pascal(key)} {`, ...numbers(t.type[key]).map((l) => `    ${l}`), '        }');
  lines.push('    }', '    public enum Motion {');
  for (const key of ['duration', 'rate']) lines.push(`        public enum ${pascal(key)} {`, ...numbers(t.motion[key]).map((l) => `    ${l}`), '        }');
  lines.push('        public enum Easing {', ...Object.entries(t.motion.easing).flatMap(([name, { value, description }]) => [doc(description, '            '), `            public static let ${name}: [Double] = [${value.join(', ')}]`]), '        }');
  lines.push('    }', '}', '');
  return lines.join('\n');
}

function rust(t) {
  const doc = (text, indent) => `${indent}/// ${text.replace(/\n/g, ' ')}`;
  const c = (hex) => { const [r, g, b] = rgb(hex); return `Rgb { r: ${hex2(r)}, g: ${hex2(g)}, b: ${hex2(b)} }`; };
  const numbers = (group, indent) => Object.entries(group).flatMap(([name, { value, description }]) => [doc(description, indent), `${indent}pub const ${screaming(name)}: f64 = ${f64(value)};`]);
  const lines = [
    `//! ${HEADER}`,
    '//! Lengths are points; durations milliseconds.',
    '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]',
    'pub struct Rgb {',
    '    pub r: u8,',
    '    pub g: u8,',
    '    pub b: u8,',
    '}',
    '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]',
    'pub struct Themed<T> {',
    '    pub light: T,',
    '    pub dark: T,',
    '}',
    '',
    'pub mod color {',
    '    use super::{Rgb, Themed};',
    ...Object.entries(t.color).flatMap(([name, v]) => [doc(v.description, '    '), `    pub const ${screaming(name)}: Themed<Rgb> = Themed { light: ${c(v.light)}, dark: ${c(v.dark)} };`]),
    '}',
    '',
    'pub mod ramp {',
    '    use super::{Rgb, Themed};',
    ...Object.entries(t.ramp).flatMap(([name, v]) => [doc(v.description, '    '), `    pub const ${screaming(name)}: Themed<[Rgb; ${v.light.length}]> = Themed { light: [${v.light.map(c).join(', ')}], dark: [${v.dark.map(c).join(', ')}] };`]),
    '}',
  ];
  for (const [path] of NUMBER_GROUPS) {
    const [head] = path;
    if (head === 'type' || head === 'motion') continue;
    lines.push('', `pub mod ${head} {`, ...numbers(at(t, path), '    '), '}');
  }
  lines.push('', 'pub mod typography {', '    pub mod family {', ...Object.entries(t.type.family).flatMap(([name, { value, description }]) => [doc(description, '        '), `        pub const ${screaming(name)}: &str = ${JSON.stringify(value)};`]), '    }');
  for (const key of ['size', 'weight', 'lineHeight', 'tracking']) lines.push(`    pub mod ${kebab(key).replace(/-/g, '_')} {`, ...numbers(t.type[key], '        '), '    }');
  lines.push('}', '', 'pub mod motion {');
  for (const key of ['duration', 'rate']) lines.push(`    pub mod ${key} {`, ...numbers(t.motion[key], '        '), '    }');
  lines.push('    pub mod easing {', ...Object.entries(t.motion.easing).flatMap(([name, { value, description }]) => [doc(description, '        '), `        pub const ${screaming(name)}: [f64; 4] = [${value.map(f64).join(', ')}];`]), '    }', '}', '');
  return lines.join('\n');
}

/** Every generated file's path and contents, from parsed tokens.json. */
export function render(tokens) {
  const found = problems(tokens);
  if (found.length) throw new Error(`tokens.json: ${found.join('; ')}`);
  return { 'generated/tokens.css': css(tokens), 'generated/tokens.js': js(tokens), 'generated/Tokens.swift': swift(tokens), 'generated/tokens.rs': rust(tokens) };
}

/** Generated paths whose committed contents differ from `render`. */
export async function stale(root = ROOT) {
  const files = render(JSON.parse(await readFile(join(root, 'tokens/tokens.json'), 'utf8')));
  const out = [];
  for (const [path, text] of Object.entries(files)) {
    const current = await readFile(join(root, path), 'utf8').catch(() => null);
    if (current !== text) out.push(path);
  }
  return out;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (process.argv.includes('--check')) {
    const paths = await stale();
    if (paths.length) {
      console.error(`stale generated token files (run \`npm run tokens\`): ${paths.join(', ')}`);
      process.exit(1);
    }
    console.log(`generated token files are current (${GENERATED.length})`);
  } else {
    const files = render(JSON.parse(await readFile(join(ROOT, 'tokens/tokens.json'), 'utf8')));
    await mkdir(join(ROOT, 'generated'), { recursive: true });
    for (const [path, text] of Object.entries(files)) await writeFile(join(ROOT, path), text);
    console.log(`wrote ${Object.keys(files).join(', ')}`);
  }
}
